#include <bits/stdc++.h>
using namespace std;

int limit;
string chars;
vector<int> slots;
string out = "[";
bool first = true;

// fill the ? slots left to right with 0..limit; increasing order keeps the output sorted
void visit(size_t i, int left) {
    if (left < 0 || left > (int)(slots.size() - i) * limit) return;
    if (i == slots.size()) {
        if (left == 0) {
            if (!first) out += ',';
            first = false;
            out += '"' + chars + '"';
        }
        return;
    }
    int pos = slots[i];
    for (int x = 0; x <= limit; x++) {
        chars[pos] = char('0' + x);
        visit(i + 1, left - x);
    }
    chars[pos] = '?';
}

int main() {
    int work;
    cin >> work >> limit >> chars;
    int fixed = 0;
    for (size_t i = 0; i < chars.size(); i++) {
        if (chars[i] == '?') slots.push_back(i);
        else fixed += chars[i] - '0';
    }
    visit(0, work - fixed);
    out += ']';
