}

import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    static int limit;
    static byte[] chars;
    static int[] slots;
    static int slotCount;
    static BufferedOutputStream out = new BufferedOutputStream(System.out, 1 << 16);
    static boolean first = true;

    // fill the ? slots left to right with 0..limit; increasing order keeps the output sorted
    static void visit(int i, int left) throws IOException {
        if (left < 0 || left > (slotCount - i) * limit) return;
        if (i == slotCount) {
            if (left == 0) {
                if (!first) out.write(',');
                first = false;
                out.write('"');
                out.write(chars);
                out.write('"');
            }
            return;
        }
        int pos = slots[i];
        for (int x = 0; x <= limit; x++) {
            chars[pos] = (byte) ('0' + x);
            visit(i + 1, left - x);
        }
        chars[pos] = '?';
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int work = nextInt();
        limit = nextInt();
        chars = next().getBytes();
        slots = new int[chars.length];
        int fixed = 0;
        for (int i = 0; i < chars.length; i++) {
            if (chars[i] == '?') slots[slotCount++] = i;
            else fixed += chars[i] - '0';
        }
        out.write('[');
        visit(0, work - fixed);
        out.write(']');
        out.write('\n');
        out.flush();
    }
}

package main

import (
	"bufio"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

var limit int
var chars []byte
var slots []int
var w = bufio.NewWriter(os.Stdout)
var first = true

// fill the ? slots left to right with 0..limit; increasing order keeps the output sorted
func visit(i, left int) {
	if left < 0 || left > (len(slots)-i)*limit {
		return
	}
	if i == len(slots) {
		if left == 0 {
			if !first {
				w.WriteByte(',')
			}
			first = false
			w.WriteByte('"')
			w.Write(chars)
			w.WriteByte('"')
		}
		return
	}
	pos := slots[i]
	for x := 0; x <= limit; x++ {
		chars[pos] = byte('0' + x)
		visit(i+1, left-x)
	}
	chars[pos] = '?'
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	work := int(nextInt())
	limit = int(nextInt())
	chars = []byte(string(next()))
	fixed := 0
	for i, c := range chars {
		if c == '?' {
			slots = append(slots, i)
		} else {
			fixed += int(c - '0')
		}
	}
	w.WriteByte('[')
	visit(0, work-fixed)
	w.WriteString("]\n")
	w.Flush()
}
